  const COLORABLE_EQUIPMENT = new Set(INVENTORY_KINDS.filter(kind => !["player", "player-gold", "coach", "ball", "rugby-ball"].includes(kind)));
  const CONE_COLORS = ["#ffc72c", "#ff6b24", "#ff4545", "#4da3ff", "#2ee878", "#ffffff", "#b45cff"];
  function coneColorChoices(attribute, selected) {
    return '<div class="cone-color-choices" aria-label="Cone color">' + CONE_COLORS.map(color =>
      '<button type="button" '+attribute+'="'+color+'" aria-label="Color '+color+'" aria-pressed="'+(selected === color)+'" style="--cone-color:'+color+'"></button>').join('') + '</div>';
  }
  function applyConeColor(node, color) {
    if (!CONE_COLORS.includes(color)) return;
    const chromatic = value => {
      if (typeof value !== "string" || !/^#[0-9a-f]{6}$/i.test(value)) return false;
      const channels = [1,3,5].map(i => parseInt(value.slice(i,i+2),16));
      return Math.max(...channels)-Math.min(...channels)>35;
    };
    const visit = part => {
      if (part.getChildren) { part.getChildren().forEach(visit); return; }
      if (!part.fill) return;
      if (part.getAttr("pacColorFill") === undefined) {
        const stops = [...(part.fillLinearGradientColorStops?.() || []), ...(part.fillRadialGradientColorStops?.() || [])];
        part.setAttr("pacColorFill", chromatic(part.fill()) || stops.some(chromatic) || part.name?.()==="flat-cone-body");
        part.setAttr("pacColorStroke", chromatic(part.stroke?.()));
      }
      if (part.getAttr("pacColorFill")) part.setAttrs({fill:color,fillPriority:"color"});
      if (part.getAttr("pacColorStroke")) part.stroke(color);
      if (part.getAttr("pacColorFill") || part.getAttr("pacColorStroke")) part.shadowColor?.(color);
    };
    visit(node);
  }

